import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:flutter/foundation.dart';

class BlockchainService {
  // TODO: Replace with actual Gara Chain RPC/API endpoint
  static const String _rpcUrl = 'https://mock.gara-chain.net/api/v1/submit-proof';

  final http.Client _client;

  BlockchainService({http.Client? client}) : _client = client ?? http.Client();

  /// Submits the reward proof (JSON) generated by Rust to the blockchain.
  /// Returns existing success if the node accepted the proof.
  Future<bool> submitRewardProof(String rewardJson) async {
    if (rewardJson.isEmpty || rewardJson == "[]") {
      debugPrint('🔗 BlockchainService: No rewards to sync.');
      return true;
    }

    debugPrint('🔗 BlockchainService: Syncing to $_rpcUrl...');
    debugPrint('📦 Payload: $rewardJson');

    try {
      final response = await _client.post(
        Uri.parse(_rpcUrl),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({
          'proof_type': 'v2v_interaction',
          'data': jsonDecode(rewardJson),
          'timestamp': DateTime.now().toIso8601String(),
        }),
      );

      if (response.statusCode >= 200 && response.statusCode < 300) {
        debugPrint('✅ BlockchainService: Sync successful! (TxHash: Mock-${DateTime.now().millisecondsSinceEpoch})');
        return true;
      } else {
        debugPrint('❌ BlockchainService: Sync failed. Code: ${response.statusCode}, Body: ${response.body}');
        return false;
      }
    } catch (e) {
      debugPrint('❌ BlockchainService: Network error: $e');
      // In a real app, we might want to queue this for retry later
      return false;
    }
  }
}
